mapper.select:
/* 수출수입심사현황 - 경보건 (4050) */
/* RevertStatAlertMapper.selectListTotCnt */

SELECT COUNT(*) totcnt
  FROM VW_TASK A

mapper.sql:
/* (수정이력)
  - 2019-10-17
      기존 화면정의서에는 승인건까지 포함되었는데, 경보건 목록에는 
      토탈텍스트,항목심사,세이프와치 상태코드가, 셋중에 하나라도, 170그룹코드의 30 - alert,
      코드가 하나라도  반드시 있는 건만 나오므로, 심사상태가 그룹코드290(액티비티) 160(승인코드),인 심사건들은
      토탈텍스트,항목심사,세이프와치 상태코드가 경보건인 경우가 있을 수 없으므로, 기본조건제약에 160코드값은 제외했음  
*/
WHERE A.ACTL_FX_REFNO = B.ACTL_FX_REFNO(+)
AND A.FX_REFNO_SRNO = B.FX_REFNO_SRNO(+)
AND A.AI_INPT_ACVT_CD IN ('160','140') 
   /* Pending, Block > 1127 이후 변경 Block, 승인 */ 


	AND A.INPT_RCP_DT BETWEEN REPLACE(#{schSdate1}, '-', '') AND REPLACE(#{schEdate1}, '-', '') 


  AND A.INPT_ATMC_BIZ_DSCD = #{inptAtmcBizDscd}


  AND B.CSNO = #{aiInptCsno}


  AND A.ACTL_FX_REFNO LIKE '%' || UPPER(#{actlFxRefno}) || '%'



  /* TOTALTEXT_AI_INPT_RST_CD, ITM_INPT_AI_INPT_RST_CD, SAFEWATCH_AI_INPT_RST_CD - 170그룹코드 */
  AND A.TOTALTEXT_AI_INPT_RST_CD = #{schTotalText}




  AND A.ITM_INPT_AI_INPT_RST_CD = #{schInptItem}




  AND A.SAFEWATCH_AI_INPT_RST_CD = #{schSafeWatch}



AND (
	A.ITM_INPT_AI_INPT_RST_CD IN ('30', '40')				/* 170그룹코드의 30(alert) 40(release) */
	OR A.TOTALTEXT_AI_INPT_RST_CD IN ('30', '40')
	OR A.SAFEWATCH_AI_INPT_RST_CD IN ('30', '40')
)
